385	const dayTagLabel = {d1:'DAY 1・9/23', d2:'DAY 2・9/24', both:'DAY 1+2'};
386	
387	function renderSpeakers(){
388	  const grid = document.getElementById('speakerGrid');
389	  SPEAKERS.forEach((s, i) => {
390	    const card = document.createElement('button');
391	    card.className = 'speaker-card';
392	    card.onclick = () => openBio(i);
393	    const photoInner = s.hasPhoto ? `<img src="${s.photo}" alt="${s.name} 頭像">` : (s.name.includes('籌備') ? '籌備中' : s.name.slice(0,1));
394	    card.innerHTML = `
395	      <span class="day-tag ${s.day}">${dayTagLabel[s.day]}</span>
396	      <div class="speaker-photo">${photoInner}</div>
397	      <div class="speaker-name">${s.name}</div>
398	      <div class="speaker-title">${s.title}</div>
399	      <div class="speaker-topic">${s.topic}</div>
400	      <span class="speaker-hint ${s.hasPhoto ? '' : 'tbd'}">${s.hasPhoto ? '查看完整簡介' : '資料籌備中'}</span>
401	    `;
402	    grid.appendChild(card);
403	  });
404	}
405	
406	function openBio(i){
407	  const s = SPEAKERS[i];
408	  const photoInner = s.hasPhoto ? `<img src="${s.photo}" alt="${s.name} 頭像">` : (s.name.includes('籌備') ? '籌備中' : s.name.slice(0,1));
409	  const linksHtml = s.links.length ? `<div style="margin-top:16px;display:flex;gap:8px;flex-wrap:wrap">${s.links.map(l=>`<a href="${l.url}" target="_blank" rel="noopener" class="chip">${l.label} ↗</a>`).join('')}</div>` : '';
410	  document.getElementById('bioContent').innerHTML = `
411	    <div class="speaker-photo">${photoInner}</div>
412	    <div class="speaker-name" style="font-size:24px;margin-top:4px">${s.name}</div>
413	    <div class="speaker-title" style="margin-top:2px">${s.title}</div>
414	    <div style="margin-top:6px;font-weight:800;color:var(--muted-2)">主題：${s.topic}</div>
415	    <p style="margin-top:14px;color:var(--muted);white-space:pre-line">${s.bio}</p>
416	    ${linksHtml}
417	  `;
418	  document.getElementById('bioModal').classList.add('show');
419	}
420	function closeBio(){ document.getElementById('bioModal').classList.remove('show'); }
421	document.getElementById('bioModal').addEventListener('click', e => { if(e.target.id==='bioModal') closeBio(); });
422	
423	renderSpeakers();
424	
425	// 倒數計時（以 9/23 09:00 台灣時間為準）
426	function updateCountdown(){
427	  const target = new Date('2026-09-23T09:00:00+08:00').getTime();
428	  const now = Date.now();
429	  const diff = target - now;
430	  if(diff <= 0){ document.getElementById('cd-d').textContent='0'; document.getElementById('cd-h').textContent='0'; document.getElementById('cd-m').textContent='0'; return; }
431	  const d = Math.floor(diff/86400000);
432	  const h = Math.floor((diff%86400000)/3600000);
433	  const m = Math.floor((diff%3600000)/60000);
434	  document.getElementById('cd-d').textContent = d;
435	  document.getElementById('cd-h').textContent = h;
436	  document.getElementById('cd-m').textContent = m;
437	}
438	updateCountdown();
439	setInterval(updateCountdown, 60000);
440	</script>
441	
442	</body>
443	</html>
