function openBio(i){
  const s = SPEAKERS[i];
  const photoInner = s.hasPhoto ? `<img src="${s.photo}" alt="${s.name} 頭像">` : (s.name.includes('籌備') ? '籌備中' : s.name.slice(0,1));
  const linksHtml = s.links.length ? `<div style="margin-top:16px;display:flex;gap:8px;flex-wrap:wrap">${s.links.map(l=>`<a href="${l.url}" target="_blank" rel="noopener" class="chip">${l.label} ↗</a>`).join('')}</div>` : '';
  document.getElementById('bioContent').innerHTML = `
    <div class="speaker-photo">${photoInner}</div>
    <div class="speaker-name" style="font-size:24px;margin-top:4px">${s.name}</div>
    <div class="speaker-title" style="margin-top:2px">${s.title}</div>
    <div style="margin-top:6px;font-weight:800;color:var(--muted-2)">主題：${s.topic}</div>
    <p style="margin-top:14px;color:var(--muted);white-space:pre-line">${s.bio}</p>
    ${linksHtml}
  `;
  document.getElementById('bioModal').classList.add('show');
}
function closeBio(){ document.getElementById('bioModal').classList.remove('show'); }
document.getElementById('bioModal').addEventListener('click', e => { if(e.target.id==='bioModal') closeBio(); });

renderSpeakers();

// 倒數計時（以 9/23 09:00 台灣時間為準）
function updateCountdown(){
  const target = new Date('2026-09-23T09:00:00+08:00').getTime();
  const now = Date.now();
  const diff = target - now;
  if(diff <= 0){ document.getElementById('cd-d').textContent='0'; document.getElementById('cd-h').textContent='0'; document.getElementById('cd-m').textContent='0'; return; }
  const d = Math.floor(diff/86400000);
  const h = Math.floor((diff%86400000)/3600000);
  const m = Math.floor((diff%3600000)/60000);
  document.getElementById('cd-d').textContent = d;
  document.getElementById('cd-h').textContent = h;
  document.getElementById('cd-m').textContent = m;
}
updateCountdown();
setInterval(updateCountdown, 60000);
</script>

</body>
</html>

