const BYMYWAY_API = 'https://event.bymyway.com/api/register';

let lastRegistration = null;

function submitRegistration(e) {
  e.preventDefault();
  const name = document.getElementById('regName').value.trim();
  const phone = document.getElementById('regPhone').value.trim();
  const sessionSelect = document.getElementById('regSession');
  const session = sessionSelect.value;
  const slug = sessionSelect.selectedOptions[0]?.dataset.slug || '';
  if (!name || !phone) { alert('請完整填寫姓名與聯絡電話'); return; }
  lastRegistration = { name, phone, session };

  // 先打後端 → 教練 LINE 立刻收到通知（不阻塞畫面，失敗也不影響使用者後續動作）
  const registerBody = { session: '【大樹小講】' + session, name, company: '', phone, email: '' };
  fetch(REGISTER_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(registerBody)
  }).catch(() => {});
  fetch(NOTIFY_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(registerBody)
  }).catch(() => {});
  // 雙寫並存：同步寫進bymyway.com自己的資料庫（有slug才打，避免未定案場次寫入失敗）
  if (slug) {
    fetch(BYMYWAY_API, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ slug, name, phone, company: '' })
    }).catch(() => {});
  }

  const form = e.target;
  const submitBtn = form.querySelector('button[type="submit"]');
  const origText = submitBtn.innerHTML;
  submitBtn.disabled = true;
  submitBtn.innerHTML = '處理中...';
  setTimeout(() => {
    hideRegisterModal();
    showSuccessModal();
    submitBtn.disabled = false;
    submitBtn.innerHTML = origText;
    form.reset();
  }, 800);
}

function generateLineMessage() {
  if (!lastRegistration) return '您好，我想報名【大樹小講．無話不談】，請協助確認席次，謝謝！';
  const r = lastRegistration;
  return `您好，我想報名【大樹小講．無話不談】\n場次：${r.session}\n姓名：${r.name}\n電話：${r.phone}\n請協助確認席次，謝謝！`;
}
function copyLineMessage() {
  const msg = generateLineMessage();
  navigator.clipboard.writeText(msg).then(() => {
    alert('已複製報名訊息，請貼到 LINE 對話框送出。');
  }).catch(() => prompt('請複製以下訊息傳送給大樹教育 LINE：', msg));
}
function sendToLine() {
  navigator.clipboard.writeText(generateLineMessage()).catch(() => {});
  window.open(LINE_URL, '_blank');
}
function showSuccessModal() {
  const m = document.getElementById('successModal');
  m.classList.remove('hidden'); m.classList.add('flex');
  const notice = document.getElementById('paymentNotice');
  const isAug25 = lastRegistration && lastRegistration.session && lastRegistration.session.includes('8/25');
  notice.classList.toggle('hidden', !isAug25);
}
function hideSuccessModal() {
  const m = document.getElementById('successModal');
  m.classList.remove('flex'); m.classList.add('hidden');
}

function initNavbar() {
  const navbar = document.getElementById('navbar');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 20) navbar.classList.add('nav-scrolled');
    else navbar.classList.remove('nav-scrolled');
  });
}

function toggleMobileMenu() {
  const menu = document.getElementById('mobileMenu');
  const icon = document.getElementById('mobileMenuIcon');
  const isOpen = menu.classList.contains('flex');
  if (isOpen) { closeMobileMenu(); }

